
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_2d_b86_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_2d_b86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.488794534470940e-01, -8.489126968752929e-01, -8.489668711810575e-01, -8.490553069476313e-01, -8.491999559894798e-01, -8.494368047854954e-01, -8.498232415084704e-01, -8.504417858200778e-01, -8.513682008907479e-01, -8.524719505422361e-01, -8.526268049653994e-01, -8.474069396681848e-01, -8.245921652507194e-01, -7.611708730096423e-01, -6.374462132542349e-01, -4.964571517397218e-01, -5.589365682279457e-01, -5.024306438189226e-01, -3.743487846061721e-02, -3.929937758234757e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


